  std::uint32_t Visit(const json::Value& schema, std::size_t depth) {
#if LIE_C17_SAMPLING
    if (auto found = compiled_.get(&schema))
      return *found;
    const auto id = New();
    compiled_.assign(&schema, id);
#else
    if (const auto found = compiled_.find(&schema); found != compiled_.end())
      return found->second;
    const auto id = New();
    compiled_[&schema] = id;
#endif
    try {
      const auto body = VisitBody(schema, depth);
      Set(id, {{body}});
    } catch (const JsonSchemaEmpty&) {
      Set(id, {});
    }
    return id;
  }

